import { test, expect } from './fixtures';

test('shows function tooltip on hover', async ({ page }) => {
  await page.goto('/');

  const tooltip = page.locator('functiontooltip').first();
  await tooltip.waitFor({ state: 'visible' });

  await tooltip.hover();

  const tooltipContent = tooltip.locator('functiontooltip').first();
  await expect(tooltipContent).toBeVisible();
});

import { test, expect } from './fixtures';

test('desktop smoke test: browse product and add to cart', async ({ page }) => {
  // Navigate to home page
  await page.goto('/#/');

  // Verify main content is visible
  await expect(page.locator('main')).toBeVisible();

  // Click on the first product card
  const productCard = page.locator('.product-card').first();
  await expect(productCard).toBeVisible();
  await productCard.click();

  // Verify product page loaded (e.g., product title or add to cart button)
  const addToCartButton = page.getByRole('button', { name: /add to cart/i });
  await expect(addToCartButton).toBeVisible();

  // Add product to cart
  await addToCartButton.click();

  // Verify cart badge shows incremented count
  const cartBadge = page.locator('.cart-badge');
  await expect(cartBadge).toHaveText('1');
});
